   289 +func (s *SocialGenericOAuth) extractFromAPI(ctx context.Context, client *http.Client) *UserInfoJson {
   290 +	s.log.Debug("Getting user info from API")
   291 +	if s.apiUrl == "" {
   292 +		s.log.Debug("No api url configured")
   293 +		return nil
   294 +	}
   295 +
   296 +	rawUserInfoResponse, err := s.httpGet(ctx, client, s.apiUrl)
   297 +	if err != nil {
   298 +		s.log.Debug("Error getting user info from API", "url", s.apiUrl, "error", err)
   299 +		return nil
   300 +	}
   301 +
   302 +	rawJSON := rawUserInfoResponse.Body
   303 +
   304 +	var data UserInfoJson
   305 +	if err := json.Unmarshal(rawJSON, &data); err != nil {
   306 +		s.log.Error("Error decoding user info response", "raw_json", rawJSON, "error", err)
   307 +		return nil
   308 +	}
   309 +
   310 +	data.rawJSON = rawJSON
   311 +	data.source = "API"
   312 +	s.log.Debug("Received user info response from API", "raw_json", string(rawJSON), "data", data.String())
   313 +	return &data
   314 +}
