   316 +func (s *SocialGenericOAuth) extractEmail(data *UserInfoJson) string {
   317 +	if data.Email != "" {
   318 +		return data.Email
   319 +	}
   320 +
   321 +	if s.emailAttributePath != "" {
   322 +		email, err := s.searchJSONForStringAttr(s.emailAttributePath, data.rawJSON)
   323 +		if err != nil {
   324 +			s.log.Error("Failed to search JSON for attribute", "error", err)
   325 +		} else if email != "" {
   326 +			return email
   327 +		}
   328 +	}
   329 +
   330 +	emails, ok := data.Attributes[s.emailAttributeName]
   331 +	if ok && len(emails) != 0 {
   332 +		return emails[0]
   333 +	}
   334 +
   335 +	if data.Upn != "" {
   336 +		emailAddr, emailErr := mail.ParseAddress(data.Upn)
   337 +		if emailErr == nil {
   338 +			return emailAddr.Address
   339 +		}
   340 +		s.log.Debug("Failed to parse e-mail address", "error", emailErr.Error())
   341 +	}
   342 +
   343 +	return ""
   344 +}
