   346 +func (s *SocialGenericOAuth) extractLogin(data *UserInfoJson) string {
   347 +	if data.Login != "" {
   348 +		s.log.Debug("Setting user info login from login field", "login", data.Login)
   349 +		return data.Login
   350 +	}
   351 +
   352 +	if s.loginAttributePath != "" {
   353 +		s.log.Debug("Searching for login among JSON", "loginAttributePath", s.loginAttributePath)
   354 +		login, err := s.searchJSONForStringAttr(s.loginAttributePath, data.rawJSON)
   355 +		if err != nil {
   356 +			s.log.Error("Failed to search JSON for login attribute", "error", err)
   357 +		}
   358 +
   359 +		if login != "" {
   360 +			return login
   361 +		}
   362 +	}
   363 +
   364 +	if data.Username != "" {
   365 +		s.log.Debug("Setting user info login from username field", "username", data.Username)
   366 +		return data.Username
   367 +	}
   368 +
   369 +	return ""
   370 +}
