   405 +func (s *SocialGenericOAuth) FetchPrivateEmail(ctx context.Context, client *http.Client) (string, error) {
   406 +	type Record struct {
   407 +		Email       string `json:"email"`
   408 +		Primary     bool   `json:"primary"`
   409 +		IsPrimary   bool   `json:"is_primary"`
   410 +		Verified    bool   `json:"verified"`
   411 +		IsConfirmed bool   `json:"is_confirmed"`
   412 +	}
   413 +
   414 +	response, err := s.httpGet(ctx, client, fmt.Sprintf(s.apiUrl+"/emails"))
   415 +	if err != nil {
   416 +		s.log.Error("Error getting email address", "url", s.apiUrl+"/emails", "error", err)
   417 +		return "", fmt.Errorf("%v: %w", "Error getting email address", err)
   418 +	}
   419 +
   420 +	var records []Record
   421 +
   422 +	err = json.Unmarshal(response.Body, &records)
   423 +	if err != nil {
   424 +		var data struct {
   425 +			Values []Record `json:"values"`
   426 +		}
   427 +
   428 +		err = json.Unmarshal(response.Body, &data)
   429 +		if err != nil {
   430 +			s.log.Error("Error decoding email addresses response", "raw_json", string(response.Body), "error", err)
   431 +			return "", fmt.Errorf("%v: %w", "Error decoding email addresses response", err)
   432 +		}
   433 +
   434 +		records = data.Values
   435 +	}
   436 +
   437 +	s.log.Debug("Received email addresses", "emails", records)
   438 +
   439 +	var email = ""
   440 +	for _, record := range records {
   441 +		if record.Primary || record.IsPrimary {
   442 +			email = record.Email
   443 +			break
   444 +		}
   445 +	}
   446 +
   447 +	s.log.Debug("Using email address", "email", email)
   448 +
   449 +	return email, nil
   450 +}
