    21 +func TestSearchJSONForEmail(t *testing.T) {
    22 +	t.Run("Given a generic OAuth provider", func(t *testing.T) {
    23 +		provider, err := NewGenericOAuthProvider(map[string]any{}, &setting.Cfg{}, featuremgmt.WithFeatures())
    24 +		require.NoError(t, err)
    25 +
    26 +		tests := []struct {
    27 +			Name                 string
    28 +			UserInfoJSONResponse []byte
    29 +			EmailAttributePath   string
    30 +			ExpectedResult       string
    31 +			ExpectedError        string
    32 +		}{
