   154 +func (s *SocialGenericOAuth) UserInfo(ctx context.Context, client *http.Client, token *oauth2.Token) (*BasicUserInfo, error) {
   155 +	s.log.Debug("Getting user info")
   156 +	toCheck := make([]*UserInfoJson, 0, 2)
   157 +
   158 +	if tokenData := s.extractFromToken(token); tokenData != nil {
   159 +		toCheck = append(toCheck, tokenData)
   160 +	}
   161 +	if apiData := s.extractFromAPI(ctx, client); apiData != nil {
   162 +		toCheck = append(toCheck, apiData)
   163 +	}
   164 +
   165 +	userInfo := &BasicUserInfo{}
   166 +	for _, data := range toCheck {
   167 +		s.log.Debug("Processing external user info", "source", data.source, "data", data)
   168 +
   169 +		if userInfo.Id == "" {
   170 +			userInfo.Id = data.Sub
   171 +		}
   172 +
   173 +		if userInfo.Name == "" {
   174 +			userInfo.Name = s.extractUserName(data)
   175 +		}
   176 +
   177 +		if userInfo.Login == "" {
   178 +			userInfo.Login = s.extractLogin(data)
   179 +		}
   180 +
   181 +		if userInfo.Email == "" {
   182 +			userInfo.Email = s.extractEmail(data)
   183 +			if userInfo.Email != "" {
   184 +				s.log.Debug("Set user info email from extracted email", "email", userInfo.Email)
   185 +			}
   186 +		}
   187 +
   188 +		if userInfo.Role == "" && !s.skipOrgRoleSync {
   189 +			role, grafanaAdmin, err := s.extractRoleAndAdminOptional(data.rawJSON, []string{})
   190 +			if err != nil {
   191 +				s.log.Warn("Failed to extract role", "err", err)
   192 +			} else {
   193 +				userInfo.Role = role
   194 +				if s.allowAssignGrafanaAdmin {
   195 +					userInfo.IsGrafanaAdmin = &grafanaAdmin
   196 +				}
   197 +			}
   198 +		}
   199 +
   200 +		if len(userInfo.Groups) == 0 {
   201 +			groups, err := s.extractGroups(data)
   202 +			if err != nil {
   203 +				s.log.Warn("Failed to extract groups", "err", err)
   204 +			} else if len(groups) > 0 {
   205 +				s.log.Debug("Setting user info groups from extracted groups")
   206 +				userInfo.Groups = groups
   207 +			}
   208 +		}
   209 +	}
   210 +
   211 +	if userInfo.Role == "" && !s.skipOrgRoleSync {
   212 +		if s.roleAttributeStrict {
   213 +			return nil, errRoleAttributeStrictViolation.Errorf("idP did not return a role attribute")
   214 +		}
   215 +		userInfo.Role = s.defaultRole()
   216 +	}
   217 +
   218 +	if s.allowAssignGrafanaAdmin && s.skipOrgRoleSync {
   219 +		s.log.Debug("AllowAssignGrafanaAdmin and skipOrgRoleSync are both set, Grafana Admin role will not be synced, consider setting one or the other")
   220 +	}
   221 +
   222 +	if userInfo.Email == "" {
   223 +		var err error
   224 +		userInfo.Email, err = s.FetchPrivateEmail(ctx, client)
   225 +		if err != nil {
   226 +			return nil, err
   227 +		}
   228 +		s.log.Debug("Setting email from fetched private email", "email", userInfo.Email)
   229 +	}
   230 +
   231 +	if userInfo.Login == "" {
   232 +		s.log.Debug("Defaulting to using email for user info login", "email", userInfo.Email)
   233 +		userInfo.Login = userInfo.Email
   234 +	}
   235 +
   236 +	if !s.IsTeamMember(ctx, client) {
   237 +		return nil, errors.New("user not a member of one of the required teams")
   238 +	}
   239 +
   240 +	if !s.IsOrganizationMember(ctx, client) {
   241 +		return nil, errors.New("user not a member of one of the required organizations")
   242 +	}
   243 +
   244 +	if !s.IsGroupMember(userInfo.Groups) {
   245 +		return nil, errMissingGroupMembership
   246 +	}
   247 +
   248 +	s.log.Debug("User info result", "result", userInfo)
   249 +	return userInfo, nil
   250 +}
