   256 +func (s *SocialGenericOAuth) extractFromToken(token *oauth2.Token) *UserInfoJson {
   257 +	s.log.Debug("Extracting user info from OAuth token")
   258 +
   259 +	idTokenAttribute := "id_token"
   260 +	if s.idTokenAttributeName != "" {
   261 +		idTokenAttribute = s.idTokenAttributeName
   262 +		s.log.Debug("Using custom id_token attribute name", "attribute_name", idTokenAttribute)
   263 +	}
   264 +
   265 +	idToken := token.Extra(idTokenAttribute)
   266 +	if idToken == nil {
   267 +		s.log.Debug("No id_token found", "token", token)
   268 +		return nil
   269 +	}
   270 +
   271 +	rawJSON, err := s.retrieveRawIDToken(idToken)
   272 +	if err != nil {
   273 +		s.log.Warn("Error retrieving id_token", "error", err, "token", fmt.Sprintf("%+v", token))
   274 +		return nil
   275 +	}
   276 +
   277 +	var data UserInfoJson
   278 +	if err := json.Unmarshal(rawJSON, &data); err != nil {
   279 +		s.log.Error("Error decoding id_token JSON", "raw_json", string(rawJSON), "error", err)
   280 +		return nil
   281 +	}
   282 +
   283 +	data.rawJSON = rawJSON
   284 +	data.source = "token"
   285 +	s.log.Debug("Received id_token", "raw_json", string(data.rawJSON), "data", data.String())
   286 +	return &data
   287 +}
