   418 +	}
   419 +
   420 +	var records []Record
   421 +
   422 +	err = json.Unmarshal(response.Body, &records)
   423 +	if err != nil {
   424 +		var data struct {
   425 +			Values []Record `json:"values"`
   426 +		}
   427 +
   428 +		err = json.Unmarshal(response.Body, &data)
   429 +		if err != nil {
   430 +			s.log.Error("Error decoding email addresses response", "raw_json", string(response.Body), "error", err)
