   148 +func (s *SocialGithub) FetchTeamMemberships(ctx context.Context, client *http.Client) ([]GithubTeam, error) {
   149 +	url := fmt.Sprintf(s.apiUrl + "/teams?per_page=100")
   150 +	hasMore := true
   151 +	teams := make([]GithubTeam, 0)
   152 +
   153 +	for hasMore {
   154 +		response, err := s.httpGet(ctx, client, url)
   155 +		if err != nil {
   156 +			return nil, fmt.Errorf("Error getting team memberships: %s", err)
   157 +		}
   158 +
   159 +		var records []GithubTeam
   160 +
   161 +		err = json.Unmarshal(response.Body, &records)
   162 +		if err != nil {
   163 +			return nil, fmt.Errorf("Error getting team memberships: %s", err)
   164 +		}
   165 +
   166 +		teams = append(teams, records...)
   167 +
   168 +		url, hasMore = s.HasMoreRecords(response.Headers)
   169 +	}
   170 +
   171 +	return teams, nil
   172 +}
