   174 +func (s *SocialGithub) HasMoreRecords(headers http.Header) (string, bool) {
   175 +	value, exists := headers["Link"]
   176 +	if !exists {
   177 +		return "", false
   178 +	}
   179 +
   180 +	pattern := regexp.MustCompile(`<([^>]+)>; rel="next"`)
   181 +	matches := pattern.FindStringSubmatch(value[0])
   182 +
   183 +	if matches == nil {
   184 +		return "", false
   185 +	}
   186 +
   187 +	url := matches[1]
   188 +
   189 +	return url, true
   190 +}
